// test:contract — contract tests generated by Schemathesis against the running server
// (FR-051, US5). Starts the server on a free port, waits for it to respond, runs
// `uvx schemathesis` on the bundle and stops the server propagating the exit code.
//
// Manual negative test: OPE_HANDLERS_MODULE=tests/contract/fixtures/health-203.ts npm run test:contract
import { spawn, spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import net from "node:net";
import path from "node:path";
import { bundlePath, repoRoot } from "./lib.mjs";

// Pinned version: the same locally and in CI.
const SCHEMATHESIS = "schemathesis@4.27.2";

/** Test merchant for Schemathesis: the ingest credential travels in every request. */
const CONTRACT_MERCHANT = {
  merchantId: "contract-test-merchant",
  ingestKeys: ["ope_contract_test_key"],
  origins: ["http://127.0.0.1"],
};

/** @returns {Promise<number>} */
function freePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, "127.0.0.1", () => {
      const address = srv.address();
      if (address === null || typeof address === "string") {
        reject(new Error("Could not get a free port"));
        return;
      }
      srv.close(() => {
        resolve(address.port);
      });
    });
    srv.on("error", reject);
  });
}

/**
 * @param {string} url
 * @param {number} timeoutMs
 */
async function waitForHealth(url, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      // Any HTTP response means the server is listening (in the negative test it is not 200).
      await fetch(url);
      return;
    } catch {
      // the server is not listening yet
    }
    await new Promise((r) => setTimeout(r, 200));
  }
  throw new Error(`The server did not respond at ${url} within ${timeoutMs} ms`);
}

/** @returns {{ cmd: string; args: string[] }} */
function serverCommand() {
  const built = path.join(repoRoot, "dist", "main.js");
  if (existsSync(built) && !process.env["OPE_HANDLERS_MODULE"])
    return { cmd: process.execPath, args: [built] };
  // tsx allows loading alternative handlers in TypeScript (negative test).
  return {
    cmd: process.execPath,
    args: [
      path.join(repoRoot, "node_modules", "tsx", "dist", "cli.mjs"),
      path.join(repoRoot, "src", "main.ts"),
    ],
  };
}

/** @returns {Promise<number>} */
async function main() {
  const uvx = spawnSync("uvx", ["--version"], { encoding: "utf8" });
  if (uvx.status !== 0) {
    console.error("test:contract — `uvx` not found. Install uv: https://docs.astral.sh/uv/");
    return 1;
  }
  if (!existsSync(bundlePath)) {
    console.error(`test:contract — ${bundlePath} does not exist. Run npm run contract:bundle.`);
    return 1;
  }

  const port = await freePort();
  const { cmd, args } = serverCommand();
  const server = spawn(cmd, args, {
    cwd: repoRoot,
    env: {
      ...process.env,
      PORT: String(port),
      HOST: "127.0.0.1",
      OPE_MERCHANTS: process.env["OPE_MERCHANTS"] ?? JSON.stringify([CONTRACT_MERCHANT]),
    },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let serverLog = "";
  /** @param {Buffer | string} chunk */
  const append = (chunk) => {
    serverLog += chunk.toString();
  };
  server.stdout.on("data", append);
  server.stderr.on("data", append);

  /** @returns {Promise<void>} */
  const stop = () =>
    new Promise((resolve) => {
      if (server.exitCode !== null) {
        resolve();
        return;
      }
      server.once("exit", () => {
        resolve();
      });
      server.kill("SIGTERM");
      setTimeout(() => {
        if (server.exitCode === null) server.kill("SIGKILL");
      }, 3000).unref();
    });

  try {
    const base = `http://127.0.0.1:${port}`;
    await waitForHealth(`${base}/v1/health`, 15000);
    console.log(`test:contract — server at ${base}; running Schemathesis…`);
    const st = spawnSync(
      "uvx",
      [
        SCHEMATHESIS,
        "run",
        bundlePath,
        "--url",
        base,
        "--checks",
        "all",
        "--phases",
        "examples,coverage,fuzzing",
        "--max-examples",
        "50",
        // Ingest credential: authenticated operations demand it (401 without it, and
        // Schemathesis also tests that path by removing the header).
        "-H",
        `X-OPE-Ingest-Key: ${CONTRACT_MERCHANT.ingestKeys[0] ?? ""}`,
        "--report",
        "junit",
        "--report-dir",
        path.join(repoRoot, ".schemathesis"),
      ],
      {
        stdio: "inherit",
        cwd: repoRoot,
        // UTF-8 output also on Windows consoles (cp1252).
        env: { ...process.env, PYTHONIOENCODING: "utf-8", PYTHONUTF8: "1" },
      },
    );
    return st.status ?? 1;
  } catch (/** @type {unknown} */ err) {
    console.error(`test:contract — ${err instanceof Error ? err.message : String(err)}`);
    console.error(serverLog);
    return 1;
  } finally {
    await stop();
  }
}

main()
  .then((code) => process.exit(code))
  .catch((/** @type {unknown} */ err) => {
    console.error(`test:contract — ${err instanceof Error ? err.message : String(err)}`);
    process.exit(1);
  });
